<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />

    <div class="optimization-table__box">
      <div class="optimization-option">
        <ul class="optimization-option__form">
          <li><h3 class="optimization-option__title">Поиск записей</h3></li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Раздел </span>

            <CustomSelect
              v-model="selectPartition"
              placeholder="Выберите"
              :options="optionsFilter"
              @updateSort="sectionSort"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">ID Записи</span>
            <input
              class="simple-input__field"
              placeholder="ID Записи"
              v-model="idInput"
              @input="updateSerch"
            />
          </li>
          <li class="optimization-option__item" v-if="isActive">
            <span class="optimization-option__text">Порядок записей</span>
            <CustomSelect
              v-model="selectSort"
              placeholder="Выберите"
              :options="selectSorts"
              @updateSort="orderBySort"
            />
          </li>

          <li class="optimization-option__more">
            <div class="optimization-option__more-btn">
              <ButtonUI
                svg="search-svg"
                text="Найти"
                buttonClass="btn--primary"
                @action="serchTable"
              />
              <ButtonUI
                text="Сбросить"
                buttonClass="btn--second"
                @action="filterReset"
              />
            </div>

            <p
              class="optimization-option__more-info"
              @click="isActive = !isActive"
            >
              {{ toggleText }}
              <img
                class="optimization-option__more-svg"
                :class="{ 'optimization-option__more-svg--rotated': isActive }"
                src="@/assets/images/svg/arrow.svg"
                alt="arrow"
              />
            </p>
          </li>
        </ul>
        <div class="optimization-option__btn-box">
          <ButtonUI
            svg="addad-t"
            text="Добавить Запись"
            buttonClass="btn--primary"
            @action="$router.push('/seo/page/create/new')"
          />
          <ButtonUI
            svg="read-log"
            text="Читать лог"
            buttonClass="btn--second"
            @action="$router.push('/seo/pages/log')"
          />
        </div>
      </div>
      <CustomTable
        :ItemRows="itemRow"
        :headerRows="headerRows"
        :lineClamp="5"
        @slot-clicked="handleButtonClick"
        :current-page="pagination.currentPage"
        :per-page="pagination.perPage"
        :total="pagination.totalPages"
        @update:currentPage="(val) => handlePageChange(val)"
      >
        <template #slot-end="{ item, emitEvent }">
          <CustomTableOption v-model="selectRole" @update:model-value="emitEvent(selectRole, item.id)"
            :options="options" />
        </template>
      </CustomTable>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';

import { useSeoPageTable } from '@/store/Table/seoPageTable.js';
import { useRouter } from 'vue-router';
import { useQueryParams } from '@/composables/useQueryParams';

import OptimizationHeader from '@/components/SEO/OptimizationHeader';

import ButtonUI from '@/components/UI/ButtonUI';
import CustomTable from '@/components/UI/CustomTable';
import CustomTableOption from '@/components/UI/CustomTableOption';
import CustomSelect from '@/components/UI/CustomSelect';

import {
  getSeoPagesFilter,
  deletSeoPage,
  copySeoPageItem,
} from '@/services/apiClient.js';

const router = useRouter();

const title = ref('SEO Страниц');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const isActive = ref(false);
const idInput = ref('');
const pagination = ref({ currentPage: 0, perPage: 0, totalPages: 0 });
const toggleText = computed(() =>
  isActive.value ? 'скрыть' : 'еще настройки'
);

const seoPageTableStore = useSeoPageTable();

const headerRows = ref([]);

const optionsFilter = ref(null);
const options = [
  {
    name: 'Редактировать',
    code: 'redact',
    error: false,
    success: false,
    svg: 'edit-svg',
    ValidateType: 'select',
  },
  {
    name: 'Создать копию',
    code: 'copy',
    error: false,
    success: false,
    svg: 'copy-svg',
    ValidateType: 'select',
  },
  {
    name: 'удалить страницу',
    code: 'delete',
    error: false,
    success: false,
    svg: 'delet-svg',
    ValidateType: 'select',
  },
];

const selectPartition = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});
const selectSort = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});
const selectSorts = ref([
  {
    name: 'Сначала свежие',
    code: 'desc',
    error: false,
    success: false,
    ValidateType: 'select',
  },
  {
    name: 'Сначала старые',
    code: 'asc',
    error: false,
    success: false,
    ValidateType: 'select',
  },
]);
const itemRow = ref([]);
const getHeaderRow = () => {
  headerRows.value = seoPageTableStore.headerRows;

  // const result = generateSitemaps();
  // if (result) {
  //   console.log(result);
  // }
};
// работа с QUERY

const {
  queryParams,
  updateQueryParams,
  buildQueryString,
  loadQueryParamsFromRoute,
} = useQueryParams();

const handlePageChange = (newPage) => {
  pagination.value.currentPage = newPage;
  // getTableItem();
  updateQueryParams();
};
const serchTable = async () => {
  await seoPageTableStore.getSeoPages(buildQueryString(queryParams.value));
  isActive.value = false;
  itemRow.value = seoPageTableStore.getItemRow;
};

const sectionSort = async (option) => {
  queryParams.value.section_id = option;
  updateQueryParams();
};

const orderBySort = async (option) => {
  queryParams.value.order_by_sort = option;
  updateQueryParams();
};

const updateSerch = (event) => {
  idInput.value = event.target.value;
  queryParams.value.id = idInput.value;
  updateQueryParams();
};

const filterReset = () => {
  queryParams.value = {};
  idInput.value = '';
  updateQueryParams();
};

const getItemRow = async () => {
  await seoPageTableStore.getSeoPages(buildQueryString(queryParams.value));
  itemRow.value = seoPageTableStore.getItemRow;
  pagination.value = seoPageTableStore.getPagination;
};

const handleButtonClick = async (name, item) => {
  if (name.code === 'redact') {
    router.push(`/seo/page/create/${item.id.value}`);
  } else if (name.code === 'copy') {
    const data = await copySeoPageItem(item.id.value);
    if (data) {
      const newItem = {
        id: {
          value: data.data?.id,
          type: 'text',
          contenteditable: false,
        },
        date: {
          value: data.data?.sort,
          type: 'text',
          contenteditable: false,
        },
        url: {
          value: data.data?.url?.url,
          type: 'link',
          contenteditable: false,
        },
        h1: {
          value: data.data?.h1,
          type: 'text',
          contenteditable: false,
        },
        title: {
          value: data.data?.title,
          type: 'text',
          contenteditable: false,
        },
        description: {
          value: data.data?.description,
          type: 'text',
          contenteditable: false,
        },
        keywords: {
          value: data.data?.keywords,
          type: 'text',
          contenteditable: false,
        },
        Noindex: {
          value: data.data?.is_no_index ? 'есть' : 'нет',
          type: 'text',
          contenteditable: false,
        },
        city: {
          value: data.data?.city?.title,
          type: 'text',
          contenteditable: false,
        },
        option: { slot: 'end', contenteditable: false, id: 1 },
      };
      itemRow.value.push(newItem);
    }
  } else if (name.code === 'delete') {
    const data = await deletSeoPage(item.id.value);
    if (data) {
      itemRow.value = itemRow.value.filter(
        (el) => item.id.value !== el.id.value
      );
    }
  }
};

const getParametrQRL = async () => {
  loadQueryParamsFromRoute();

  const data = await getSeoPagesFilter();

  optionsFilter.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));

  if (queryParams.value.section_id) {
    selectPartition.value = optionsFilter.value.find(
      (el) => el.code == queryParams.value.section_id
    );
  }
  if (queryParams.value.id) {
    idInput.value = queryParams.value.id;
  }

  if (queryParams.value.order_by_sort) {
    selectSort.value = selectSorts.value.find(
      (el) => el.code === queryParams.value.order_by_sort
    );
  }
};

onMounted(() => {
  loadQueryParamsFromRoute();
  getHeaderRow();
  getParametrQRL();
  getItemRow();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 12px 16px;
  width: calc(100% - 32px);
  display: flex;
  flex-direction: column;

  @media (max-width: 1024px) {
    width: calc(100% - 40px);
    margin-top: 70px;
    justify-content: space-between;
    height: calc(100vh - 60px);
  }

  &-table__box {
    height: calc(100vh - 100px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  &-option {
    display: flex;
    justify-content: space-between;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 16px 24px;

    @media (max-width: 1024px) {
      flex-direction: column-reverse;
      gap: 20px;
    }

    &__form {
      display: flex;
      flex-direction: column;
      max-width: 480px;
      width: 480px;
    }

    &__btn-box {
      display: flex;
      gap: 16px;
    }

    &__title-box {
      display: flex;
      justify-content: space-between;
    }
    &__title {
      margin-top: 0;
      margin-bottom: 10px;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      width: 100%;
    }

    &__text-box {
      display: flex;
    }

    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }

    &__more {
      display: flex;
      align-items: center;
      justify-content: space-between;

      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }

      &-info {
        color: #3366ff;
      }
      &-svg {
        transition: transform 0.3s ease;
        &--rotated {
          transform: rotate(180deg);
        }
      }
    }
  }
}
</style>
