import { defineStore } from 'pinia';
import { getSeoPages } from '@/services/apiClient.js';

export const useSeoPageTable = defineStore('useSeoPageTable', {
  state: () => ({
    data: null,
    itemRow: [],
    headerRows: [
      {
        name: 'ID',
        width: '20px',
        helper: false,
      },
      {
        name: 'Сорт.',
        helper: false,
        width: '50px',
      },
      {
        name: 'H1',
        helper: false,
        width: '100px',
      },
      {
        name: 'Title',
        helper: false,
        width: '100px',
      },
      {
        name: 'Description',
        helper: false,
        width: '100px',
      },
      {
        name: 'Keywords',
        helper: false,
        width: '100px',
      },
      {
        name: 'Noindex',
        helper: false,
        width: '75px',
      },
      {
        name: 'Город',
        helper: false,
        width: '100px',
      },
      {
        name: '',
        helper: false,
        width: '75px',
      },
    ],
    pagination: { currentPage: 0, perPage: 0, totalPages: 0 },
  }),

  actions: {
    async getSeoPages(option) {
      const data = await getSeoPages(option);
      this.pagination.currentPage = data.current_page;
      this.pagination.perPage = data.total_count;
      this.pagination.totalPages = data.total_page;
      this.data = data;
      this.itemRow = data?.data.map((item) => ({
        id: {
          value: item?.id,
          type: 'text',
          contenteditable: false,
        },
        date: {
          value: item?.sort,
          type: 'text',
          contenteditable: false,
        },
        h1: {
          value: item?.h1,
          type: 'text',
          contenteditable: false,
        },
        title: {
          value: item?.title,
          type: 'text',
          contenteditable: false,
        },
        description: {
          value: item?.description,
          type: 'text',
          contenteditable: false,
        },
        keywords: {
          value: item?.keywords,
          type: 'text',
          contenteditable: false,
        },
        Noindex: {
          value: item?.is_no_index ? 'есть' : 'нет',
          type: 'text',
          contenteditable: false,
        },
        city: {
          value: item?.city?.title,
          type: 'text',
          contenteditable: false,
        },
        option: { slot: 'end', contenteditable: false, id: 1 },
      }));
    },

    //  siteMapInfoErrorFetch(){
    //  }
  },

  getters: {
    getHeaderRow: (state) => state.headerRows,
    getItemRow: (state) => state.itemRow,
    getPagination: (state) => state.pagination,
  },
});
